<?php if ($documents === []): ?><div class="empty-state"><span class="empty-icon"><?= icon('documents', 'h-7 w-7') ?></span><h3>No encontramos documentos</h3><p>Prueba con otros filtros o términos de búsqueda.</p><a href="<?= e(url('/documentos')) ?>" class="btn-secondary mt-4">Ver toda la biblioteca</a></div><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Documento</th><th>Tipo</th><th>Fase PHVA</th><th>Versión</th><th>Estado</th><th>Actualización</th><th><span class="sr-only">Ver</span></th></tr></thead><tbody><?php foreach ($documents as $document): ?><tr><td><div class="flex max-w-[470px] items-center gap-3"><span class="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-blue-50 text-blue-600"><?= icon($document['tipo'] === 'Politica' ? 'shield-plain' : 'document', 'h-4 w-4') ?></span><div><a href="<?= e(url('/documentos/' . $document['id'])) ?>" class="text-xs font-semibold leading-5 text-slate-800 hover:text-blue-600"><?= e($document['nombre_documento']) ?></a><p class="mt-1 font-mono text-[10px] text-slate-400"><?= e($document['codigo_estandar']) ?></p></div></div></td><td><span class="text-xs text-slate-500"><?= e($document['tipo']) ?></span></td><td><span class="phase-badge phase-<?= strtolower($document['fase_phva']) ?>"><?= e($document['fase_phva']) ?></span></td><td><span class="text-xs font-medium text-slate-600">v<?= (int) $document['version'] ?></span></td><td><span class="badge <?= status_class($document['estado']) ?>"><?= e($document['estado']) ?></span></td><td><time class="whitespace-nowrap text-xs text-slate-500"><?= format_date($document['updated_at']) ?></time></td><td><a href="<?= e(url('/documentos/' . $document['id'])) ?>" class="btn-icon h-8 w-8" aria-label="Abrir documento"><?= icon('chevron-right', 'h-4 w-4') ?></a></td></tr><?php endforeach; ?></tbody></table></div><div class="border-t border-slate-100 px-5 py-3 text-xs text-slate-400"><?= count($documents) ?> documentos en esta vista.</div><?php endif; ?></section>
